/*
 * File purpose: animate actual recorded LVGL captures and keep loaded screen pixels
 * aligned with their state.
 *
 * This browser module replays PNGs already generated by the host simulator; it neither
 * runs CAN decoding nor changes scenario inputs. The clock and browser binding are
 * separate so deterministic tests can inject timing/image completion. CommonJS exports
 * support those tests while the generated HTML inlines this same source for offline
 * playback.
 */
"use strict";

/*
 * Create a timestamp-based playback clock with injectable browser timing for deterministic
 * tests.
 *
 * Inputs: captures is an ordered array with tick_ms timestamps; environment provides
 * now/requestFrame/cancelFrame in the same millisecond time origin; optional onUpdate
 * receives state snapshots. Returns control methods sharing closure state (position,
 * playing, speed, loop and pending callback). Empty/single/zero-duration recordings remain
 * stationary. Input ordering is established by the Python runner, not revalidated here.
 * Initial publication happens before returning controls.
 */
function createPlayback(captures, environment, onUpdate = null) {
  const start = captures.length ? captures[0].tick_ms : 0;
  const end = captures.length ? captures[captures.length - 1].tick_ms : 0;
  const duration = end - start;
  let position = start;
  let playing = false;
  let speed = 1;
  let loop = true;
  let lastWall = environment.now();
  let animationId = null;

  /*
   * Find the final capture at or before the playhead without assuming regular capture
   * spacing.
   *
   * Inputs: none; reads closure captures/position. Returns -1 for no captures, otherwise the
   * floor index using an upper-midpoint binary search. It does not change playback state or
   * interpolate an image; ordered timestamps are required.
   */
  function frameIndex() {
    if (!captures.length) return -1;
    let low = 0;
    let high = captures.length - 1;
    while (low < high) {
      const middle = Math.ceil((low + high) / 2);
      if (captures[middle].tick_ms <= position) low = middle;
      else high = middle - 1;
    }
    return low;
  }

  /*
   * Return a copy of the playhead and control state for rendering or verification.
   *
   * Inputs: none. Returns a new object containing scenario milliseconds, selected capture
   * index and current play/speed/loop flags. Nested capture state is not returned or
   * mutated. Calling it does not advance the wall clock.
   */
  function getState() {
    return { position_ms: position, index: frameIndex(), playing, speed, loop };
  }

  /*
   * Notify the renderer after a time or control change.
   *
   * Inputs: none. Returns undefined; synchronously calls onUpdate with a freshly computed
   * state when supplied. Exceptions from the callback propagate rather than being hidden;
   * publication itself does not schedule animation.
   */
  function publish() {
    if (onUpdate) onUpdate(getState());
  }

  /*
   * Cancel the next animation callback when playback stops.
   *
   * Inputs: none. Returns undefined; passes the nonnull pending identifier to the
   * environment and clears it. Null identifiers skip cancellation, allowing repeated
   * pause/destroy without a duplicate cancellation.
   */
  function cancelAnimation() {
    if (animationId !== null) environment.cancelFrame(animationId);
    animationId = null;
  }

  /*
   * Advance scenario time using elapsed clock milliseconds and the selected playback speed.
   *
   * Input: wall is milliseconds in the environment clock origin. Returns undefined; if
   * active, applies max(0, wall-lastWall)*speed and updates lastWall. Nonlooping completion
   * clamps at end, clears playing and cancels; looping overshoot wraps modulo recorded
   * duration. Exact end remains visible until the next positive overshoot. It changes clock
   * state without publishing or loading an image.
   */
  function advance(wall) {
    if (!playing) return;
    position += Math.max(0, wall - lastWall) * speed;
    lastWall = wall;
    if (position >= end && !loop) {
      position = end;
      playing = false;
      cancelAnimation();
    } else if (position > end && duration > 0) {
      position = start + (position - start) % duration;
    }
  }

  /*
   * Process one browser animation frame and request another while playback remains active.
   *
   * Input: wall is the animation callback timestamp. Returns undefined; clears the consumed
   * callback ID, advances time, publishes controls/capture choice and schedules the next
   * callback only if still playing. Cancellation/completion therefore leaves no new queued
   * frame.
   */
  function animate(wall) {
    animationId = null;
    advance(wall);
    publish();
    if (playing) animationId = environment.requestFrame(animate);
  }

  /*
   * Start playback, restarting at the first capture after a nonlooping completion.
   *
   * Inputs: none. Returns undefined; active, short or nonpositive-duration recordings are
   * guarded. At the end it resets to start; it then records the current wall origin, marks
   * playing, publishes immediately and queues animation. A repeated play call does not
   * create parallel callback chains.
   */
  function play() {
    if (playing || captures.length < 2 || duration <= 0) return;
    if (position >= end) position = start;
    lastWall = environment.now();
    playing = true;
    publish();
    animationId = environment.requestFrame(animate);
  }

  /*
   * Preserve elapsed scenario time and stop requesting animation frames.
   *
   * Inputs: none. Returns undefined; accounts for wall time accrued since the last frame
   * before clearing playing, cancelling any queued callback and publishing. It changes no
   * captured pixels/state directly and remains usable as destroy.
   */
  function pause() {
    advance(environment.now());
    playing = false;
    cancelAnimation();
    publish();
  }

  /*
   * Move to a bounded scenario timestamp while preserving the current play or pause state.
   *
   * Input: milliseconds is a finite number in the recording time range. Nonfinite values are
   * ignored; other values clamp to start/end. Returns undefined; resets the wall origin so
   * the next frame does not add time from before the seek, then publishes while retaining
   * playing.
   */
  function seek(milliseconds) {
    if (!Number.isFinite(milliseconds)) return;
    position = Math.min(end, Math.max(start, milliseconds));
    lastWall = environment.now();
    publish();
  }

  /*
   * Apply a supported speed after accounting for time elapsed under the previous speed.
   *
   * Input: value must exactly match 0.25, 0.5, 1, 2 or 4. Returns undefined; unsupported
   * values do nothing. Current elapsed time is charged at the old speed before
   * setting/publishing the new multiplier, preserving continuity.
   */
  function setSpeed(value) {
    if (![0.25, 0.5, 1, 2, 4].includes(value)) return;
    advance(environment.now());
    speed = value;
    publish();
  }

  /*
   * Change loop behavior without discarding elapsed scenario time.
   *
   * Input: value is coerced to Boolean. Returns undefined; first advances using the old loop
   * setting, then stores/publishes the new one. Enabling loop after already stopped
   * completion does not itself restart playback.
   */
  function setLoop(value) {
    advance(environment.now());
    loop = Boolean(value);
    publish();
  }

  /*
   * Return to the first capture and start the recording again.
   *
   * Inputs: none. Returns undefined; seek publishes the first position and resets its wall
   * origin, then play starts if needed. An already-playing clock remains in its single
   * callback chain rather than being duplicated.
   */
  function replay() {
    seek(start);
    play();
  }

  publish();
  return { getState, play, pause, seek, setSpeed, setLoop, replay, destroy: pause };
}

/*
 * Bind recorded playback to browser controls and commit each image together with its own
 * decoded state.
 *
 * Inputs: captures includes tick_ms/image/state, document supplies the viewer element IDs
 * and window supplies browser timing/Image/matchMedia APIs. Returns the clock controller.
 * Controls disable when motion is impossible, and reduced-motion preference only
 * suppresses initial autoplay. It creates image candidates separately from the displayed
 * node to prevent a partially loaded or obsolete capture replacing pixels/state.
 */
function mountPlayback(captures, document, window) {
  const slider = document.getElementById("time");
  const button = document.getElementById("play");
  const replayButton = document.getElementById("replay");
  const speedControl = document.getElementById("speed");
  const loopControl = document.getElementById("loop");
  const viewControl = document.getElementById("view");
  const playhead = document.getElementById("playhead");
  const stamp = document.getElementById("stamp");
  const stateText = document.getElementById("state");
  const message = document.getElementById("message");
  const error = document.getElementById("error");
  let displayedImage = document.getElementById("frame");
  let requestedIndex = -1;
  let requestVersion = 0;
  let playback;
  const hasMotion = captures.length > 1 && captures[captures.length - 1].tick_ms > captures[0].tick_ms;
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  slider.min = captures.length ? captures[0].tick_ms : 0;
  slider.max = captures.length ? captures[captures.length - 1].tick_ms : 0;
  slider.step = 1;
  slider.disabled = !hasMotion;
  for (const control of [button, replayButton, speedControl, loopControl]) control.disabled = !hasMotion;
  displayedImage.hidden = true;
  if (!captures.length) stamp.textContent = "No captured screen";
  message.textContent = !captures.length ? "No captures were requested for this recording."
    : !hasMotion ? "Single capture: the recorded screen is stationary."
    : reducedMotion ? "Reduced-motion preference: playback starts paused."
    : "Recorded screen captures. Edit scenario.json and rerun to change the inputs.";

  /*
   * Load a candidate image and reject callbacks from captures superseded by a newer seek.
   *
   * Input: index is the selected capture index; negative or already requested indices are
   * no-ops. Returns undefined; increments a request-version token and sets an Image source,
   * starting asynchronous load. Existing image/state remain paired until success. Only the
   * current version may change visible output, including after rapid seeks.
   */
  function requestCapture(index) {
    if (index < 0 || index === requestedIndex) return;
    requestedIndex = index;
    const version = ++requestVersion;
    const item = captures[index];
    const view = viewControl ? viewControl.value : "main";
    const source = item.views && item.views[view] ? item.views[view] : item.image;
    const candidate = new window.Image();
    candidate.id = "frame";
    candidate.alt = "Actual dashboard rendered by LVGL at " + (item.tick_ms / 1000).toFixed(3) + " seconds";
    candidate.width = 480;
    candidate.height = 272;
    error.textContent = "";
    /*
     * Swap the already-loaded image and its matching state in one event callback.
     *
     * Inputs: load event arguments are unused; this closure retains item/index/version.
     * Returns undefined; obsolete versions stop before any mutation. Success replaces the
     * displayed DOM node with the loaded 480x272 candidate, then writes that same capture's
     * JSON state/timestamp and clears errors. The playhead may advance independently while
     * loading.
     */
    candidate.onload = function commitCapture() {
      if (version !== requestVersion) return;
      candidate.hidden = false;
      displayedImage.replaceWith(candidate);
      displayedImage = candidate;
      stateText.textContent = JSON.stringify(item.state, null, 2);
      stamp.textContent = (item.tick_ms / 1000).toFixed(3) + " s · capture " + (index + 1) + "/" + captures.length;
      error.textContent = "";
    };
    /*
     * Expose a missing capture and clear the screen/state pair before stopping playback.
     *
     * Inputs: image-error event arguments are unused; this closure identifies the failed
     * capture/version. Returns undefined; obsolete errors are ignored. The current failure
     * first seeks to that capture and pauses, then hides the image, clears decoded state and
     * prints its missing filename. Pinning time before pause prevents late wall time from
     * scheduling another capture and hiding the error.
     */
    candidate.onerror = function rejectCapture() {
      if (version !== requestVersion) return;
      // Pin the failed capture before pausing so a late callback cannot advance into another image request.
      if (playback) {
        playback.seek(item.tick_ms);
        playback.pause();
      }
      displayedImage.hidden = true;
      stateText.textContent = "";
      stamp.textContent = "Capture unavailable";
      error.textContent = "Unable to load capture: " + source + ". Keep the PNG files beside index.html.";
    };
    candidate.src = source;
  }

  /*
   * Update the timestamp controls while keeping displayed capture state tied to its loaded
   * image.
   *
   * Input: state is a clock snapshot. Returns undefined; writes range/playhead/ARIA
   * text/button/speed/loop state and requests its capture index. It does not write decoded
   * capture JSON itself: commitCapture performs that write only once matching pixels are
   * loaded.
   */
  function updateControls(state) {
    slider.value = state.position_ms;
    const total = captures.length ? captures[captures.length - 1].tick_ms : 0;
    playhead.textContent = (state.position_ms / 1000).toFixed(3) + " / " + (total / 1000).toFixed(3) + " s";
    slider.setAttribute("aria-valuetext", (state.position_ms / 1000).toFixed(3) + " seconds");
    button.textContent = state.playing ? "Pause" : "Play";
    button.setAttribute("aria-label", state.playing ? "Pause recorded playback" : "Play recorded playback");
    speedControl.value = String(state.speed);
    loopControl.checked = state.loop;
    requestCapture(state.index);
  }

  if (viewControl) viewControl.addEventListener("change", function changeScreen() {
    const index = requestedIndex;
    requestedIndex = -1;
    requestCapture(index);
  });

  const environment = {
    /*
     * Read the same monotonic time origin used by browser animation callbacks.
     *
     * Inputs: none. Returns performance.now() milliseconds; no wall-clock dates or scenario
     * timestamps are read.
     */
    now() { return window.performance.now(); },
    /*
     * Request a browser paint callback for the recording clock.
     *
     * Input: callback receives the browser animation timestamp. Returns its
     * requestAnimationFrame cancellation ID; browser scheduling may be throttled, so elapsed
     * time rather than callback count drives playback.
     */
    requestFrame(callback) { return window.requestAnimationFrame(callback); },
    /*
     * Cancel a pending browser paint callback.
     *
     * Input: identifier is the queued browser animation ID. Returns undefined; forwards
     * cancellation without changing scenario data or image requests.
     */
    cancelFrame(identifier) { window.cancelAnimationFrame(identifier); },
  };
  playback = createPlayback(captures, environment, updateControls);
  /*
   * Toggle playing and paused states from the primary button.
   *
   * Inputs: click event arguments unused. Returns undefined; queries playing at click time,
   * then pauses with elapsed-time accounting or starts via the guarded play path.
   */
  button.addEventListener("click", function togglePlay() {
    if (playback.getState().playing) playback.pause();
    else playback.play();
  });
  /*
   * Restart from the beginning when the replay button is used.
   *
   * Inputs: click event arguments unused. Returns undefined; delegates to replay, preserving
   * the selected speed/loop settings.
   */
  replayButton.addEventListener("click", function replayRecording() { playback.replay(); });
  /*
   * Seek to the slider's millisecond timestamp without changing play/pause.
   *
   * Inputs: input event arguments unused; reads slider.value and converts its string to a
   * number. Returns undefined; clock bounds/finite guard apply before publication and
   * asynchronous capture selection.
   */
  slider.addEventListener("input", function seekRecording() { playback.seek(Number(slider.value)); });
  /*
   * Apply the selected playback speed.
   *
   * Inputs: change event arguments unused; reads the select string as Number. Returns
   * undefined; setSpeed accepts only the five supported multipliers and accounts for time
   * under the prior multiplier.
   */
  speedControl.addEventListener("change", function changeSpeed() { playback.setSpeed(Number(speedControl.value)); });
  /*
   * Enable or disable repeating the recording at its end.
   *
   * Inputs: change event arguments unused; reads the checkbox Boolean. Returns undefined;
   * setLoop owns elapsed-time accounting and publication. It does not regenerate captures.
   */
  loopControl.addEventListener("change", function changeLoop() { playback.setLoop(loopControl.checked); });
  if (hasMotion && !reducedMotion) playback.play();
  return playback;
}

if (typeof module !== "undefined" && module.exports) module.exports = { createPlayback, mountPlayback };
